#include "stdafx.h"#include "HcdElementBase.h"struct SHSEL_P{#include "PrivateVars/HSEL.h"};class KHSEL : public KHcdElementBase  , protected SHSEL_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _HSEL("HSEL", KHSEL::Create);IHcdElement *KHSEL::Create(){  return new KHSEL;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KHSEL, 4 )void KHSEL::InitParm(){#include "PrivateVars/HSEL.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KHSEL::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KHSEL::StepCalc( SStepCalcParams &params ){  if( INU0 >= Y )  {    YHI = 0;    OUTD0 = INU0;  }  else  {    YHI = 1;    OUTD0 = Y;  }}